def solve(data):
    capacity = data['capacity']
    ops = data['ops']
    reads = []
    keys = []
    cache = {}
    for op in ops:
        if op[0] == 'put':
            if len(cache) >= capacity:
                evict_key = min(cache, key=cache.get)
                del cache[evict_key]
            cache[op[1]] = op[2]
            reads.append(None)
            keys.append(op[1])
        elif op[0] == 'get':
            if op[1] in cache:
                reads.append(cache[op[1]])
                keys.append(op[1])
            else:
                reads.append(None)
    return {'reads': reads, 'keys': keys}
