def solve(data):
    capacity = data['capacity']
    ops = data['ops']
    reads = []
    keys = []

    cache = {}

    for op in ops:
        if op[0] == 'put':
            if len(cache) == capacity:
                cache.pop(next(iter(cache)))
            cache[op[1]] = op[2]
            keys.append(op[1])
        elif op[0] == 'get':
            if op[1] in cache:
                keys.remove(op[1])
                keys.append(op[1])
                reads.append(cache[op[1]])
            else:
                reads.append(None)
        else:
            raise ValueError("Unknown operation")

    return {"reads": reads, "keys": keys}
```

