def solve(data):
    window = data['window']
    values = data['values']
    records = []

    for i in range(len(values)):
        if i < window:
            records.append({\"count\": 0, \"sum\": 0, \"min\": None, \"max\": None})
        else:
            records.append({\n                \"count\": i - window + 1,\n                \"sum\": sum(values[i - window:i]),\n                \"min\": min(values[i - window:i]),\n                \"max\": max(values[i - window:i])\n            })
    return records
